-- The two checklists published on 2026-11-20: Taking a Compliment Without
-- Deflecting (Compliments) and Living Well With a Housemate (Roommates).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-20`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('taking-a-compliment-without-deflecting', 'Taking a Compliment Without Deflecting', 'Open this if praise makes you squirm and you hear yourself brushing it off before the sentence is finished. It gives you something to say instead, and a way to let the good thing land rather than bounce.', 'Compliments', '["Say thank you and stop there — The whole sentence is two words, and anything after it tends to undo them.", "Hold off on returning it instantly — Trading compliments is polite, but it closes the moment too fast.", "Notice the squirm without acting on it — The discomfort passes in seconds if you do not fill it with words.", "Repeat the compliment to yourself later — Hearing it in your own voice is how it gets past the filter.", "Ask what they noticed, if you want more — A question turns vague praise into something specific you can keep.", "Write down the ones that surprised you — A short list is useful on the days you cannot find anything good.", "Give one honest compliment this week — Being on the other side shows you how easy it is to mean it.", "Let a thank-you be enough for the giver — Arguing with praise quietly tells someone their judgment is wrong."]'::jsonb, 'as needed', array['Self-Esteem', 'Self-Compassion', 'Relationships']::text[], 1, '2026-11-20T16:00:00+00:00'::timestamptz),
  ('living-well-with-a-housemate', 'Living Well With a Housemate', 'Open this when you share a home with someone you did not grow up with and the small frictions are starting to add up. It sets out the few habits and conversations that keep a shared place easy to live in.', 'Roommates', '["Raise the small thing while it is small — A dish mentioned today is a conversation, and a month of dishes is a fight.", "Agree on quiet hours out loud — A stated time beats both of you guessing and quietly resenting.", "Split the jobs by what each minds least — People keep doing the chores they do not hate without being chased.", "Keep one shared shelf and one private one — Clear lines about food head off most kitchen arguments.", "Say when you need the place to yourself — Asking for an evening alone is normal and easier than hinting.", "Settle money on the same day each month — A fixed date keeps rent and bills out of the friendship.", "Knock, even when the door is open — Small formalities make a shared home feel like your own.", "Have one friendly check-in a month — Ten minutes on what is working stops problems from piling up."]'::jsonb, 'weekly', array['Boundaries', 'Communication', 'Relationships']::text[], 1, '2026-11-20T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
